# frozen_string_literal: true

require Rails.root.join("lib/messaging_fixtures").to_s

# The committed files are generated by `rake command_tower:messaging:fixtures`
# (rails_app/lib/tasks/messaging_fixtures.rake); this keeps the generator reproducible.
RSpec.describe MessagingFixtures, :aggregate_failures, :messaging_notification_types do
  # Other messaging specs reset the registry the host initializer fills at boot, so register the
  # same sample types the initializer does.
  before do
    shared = { inbox_available: true, user_configurable: true, mandatory: false,
               category_key: "studio", category_label: "Studio", category_order: 10 }
    both = ->(channels) { { "channels" => channels.index_with { true }, "inbox" => true } }
    register_and_seal_notification_types(
      *[
        { key: "class_canceled", label: "Class canceled", type_order: 10, message: "ClassCanceled",
          allowed_channels: %w[email push sms pushover], default_channels: %w[email push],
          default_preference_state: both.call(%w[email push]) },
        { key: "membership_renewal", label: "Membership renewal", type_order: 20, message: "MembershipRenewal",
          allowed_channels: %w[email push], default_channels: %w[email],
          default_preference_state: both.call(%w[email]) },
        { key: "class_reminder", label: "Class reminder", type_order: 30, message: "ClassReminder",
          allowed_channels: %w[push sms], default_channels: %w[push],
          default_preference_state: both.call(%w[push]) },
        { key: "check_in_ready", label: "Check-in ready", type_order: 40, message: "CheckInReady",
          allowed_channels: %w[email], default_channels: %w[email],
          default_preference_state: both.call(%w[email]) },
        { key: "promotional_announcement", label: "Promotional announcement", type_order: 50,
          message: "CommandTower::Messaging::AnnouncementDefinition",
          allowed_channels: %w[email], default_channels: %w[email],
          default_preference_state: both.call(%w[email]) }
      ].map { |attributes| build_notification_type_declaration(**shared, **attributes) }
    )
  end

  let(:files) { described_class.files }
  let(:relative_names) { files.keys.map { |path| path.delete_prefix("#{described_class::ROOT}/") } }
  let(:impersonated_path) { File.join(described_class::DOCUMENTS_DIR, "sample_inbox_impersonated.json") }

  it "writes the documents, email parts and gallery payloads" do
    expect(relative_names).to include(
      "ui/documents/sample_inbox.json", "ui/email/class_canceled_email_defined.html",
      "messaging/gallery/list.json", "messaging/gallery/preview_class_canceled_america_new_york.json"
    )
  end

  it "matches the committed files" do
    files.each do |path, content|
      expect(File.read(path)).to eq(content), "#{path} is stale; rerun the generator"
    end
  end

  it "keeps the check-in code out of the impersonated document" do
    expect(files.fetch(impersonated_path)).not_to include("482913")
  end

  it "carries no unsubscribe token" do
    expect(files.values.join).not_to include("token=")
  end
end
